// Pure, filesystem-backed repair of assistant message content generated by an LLM.
//
// Scope (per spec): at turn_end, only assistant messages are inspected. Any path-
// like substring inside assistant text/thinking/tool-call arguments that an LLM
// misspelled (e.g. `src/Kry xn.Core/Foo.cs`) is repaired to the real path using the
// SAME filesystem-backed canonicalization authority Path Guard already relies on.
//
// Guarantees:
//   - Only unambiguously resolvable corrections are applied (never ambiguous, never
//     nonexistent). Every candidate must resolve to a real filesystem entry.
//   - Prose is never rewritten on its own. A span is only touched when the collapsed
//     (whitespace-stripped) string resolves to an existing path.
//   - The input is never mutated; a new content array is returned when (and only when)
//     something changed.
//   - Tool-call identity (id/name/namespace/thoughtSignature) and all unrelated
//     arguments are preserved. Non-path content is untouched.

import { existsSync } from "node:fs";

import {
    canonicalizeNestedPowerShellCommand,
    canonicalizeQuotedShellPaths,
    canonicalizeSetContentWriteTarget,
    canonicalizeUnquotedShellPaths,
    resolveExistingPath,
    resolveWritePath,
} from "./canonicalize.ts";

import type {
    ContextEditableContent,
    ContextEditEntryDraft,
} from "@earendil-works/pi-coding-agent";

// ------------------------------------------------------------------ types

// Mirrors the Pi `@earendil-works/pi-ai` JSON types closely enough for local
// structural typing without importing a non-direct dependency.
type JsonValue = null | boolean | number | string | readonly JsonValue[] | JsonObject;
type JsonObject = { [key: string]: JsonValue };

export interface TextContent {
    type: "text";
    text: string;
    textSignature?: string;
}

export interface ThinkingContent {
    type: "thinking";
    thinking: string;
    thinkingSignature?: string;
    redacted?: boolean;
}

export interface ToolCall {
    type: "toolCall";
    id: string;
    name: string;
    arguments: JsonObject;
    thoughtSignature?: string;
    namespace?: string;
}

export type AssistantContent = (TextContent | ThinkingContent | ToolCall)[];

export interface Repair {
    /** The exact original span that was replaced (with its original whitespace). */
    original: string;
    /** The corrected replacement. */
    actual: string;
}

export interface AssistantContentRepair {
    content: AssistantContent;
    changed: boolean;
    repairs: Repair[];
}

// ------------------------------------------------------------------ path spans inside prose

// Characters that terminate a path span when scanning outward from a whitespace
// boundary. Deliberately excludes `.` and path separators, `-`, `_`, `:` so file
// extensions, drive letters and path separators are not truncated.
const PATH_BOUNDARY = /[ \s"'`|&<>()\[\],;]/;

/**
 * Repair every unambiguously resolvable path span that spans a single whitespace
 * gap. Uses the boundary-walk technique already employed by the shell canonicalizer:
 * from each run of whitespace, expand left and right past delimiter characters to
 * recover the two adjacent path-like tokens, collapse the gap, and ask the
 * filesystem-backed resolver whether the collapsed path exists.
 */
export function repairPathSpansInText(text: string, cwd: string): {
    text: string;
    repairs: Repair[];
} {
    const repairs: Repair[] = [];
    const candidates: Array<{
        start: number;
        end: number;
        original: string;
        actual: string;
    }> = [];

    const whitespace = /[ \t\f\r]+/g;
    let match: RegExpExecArray | null;
    while ((match = whitespace.exec(text)) !== null) {
        const gapStart = match.index;
        const gapEnd = gapStart + match[0].length;

        let leftStart = gapStart;
        while (leftStart > 0 && !PATH_BOUNDARY.test(text[leftStart - 1])) leftStart--;

        let rightEnd = gapEnd;
        while (rightEnd < text.length && !PATH_BOUNDARY.test(text[rightEnd])) rightEnd++;

        const left = text.slice(leftStart, gapStart);
        const right = text.slice(gapEnd, rightEnd);

        if (!left || !right) continue;
        // Require at least one side to look like a path, and the collapsed union to
        // actually contain a separator before spending a filesystem lookup.
        const leftHasSep = left.includes("/");
        const leftHasBack = left.includes("\\");
        const rightHasSep = right.includes("/");
        const rightHasBack = right.includes("\\");
        if (!leftHasSep && !leftHasBack && !rightHasSep && !rightHasBack) continue;
        const collapsed = left + right;
        if (!collapsed.includes("/") && !collapsed.includes("\\")) continue;

        // The collapsed union either corrects a misspelling ("corrected") or is
        // already the real, canonical path ("unchanged"). Both are valid targets; the
        // downstream `existsSync(original)` guard rejects intentional whitespace.
        const resolution = resolveExistingPath(collapsed, cwd);
        if (resolution.kind !== "corrected" && resolution.kind !== "unchanged") continue;

        // A path that legitimately contains the whitespace must never be rewritten.
        const original = text.slice(leftStart, rightEnd);
        if (existsSync(original)) continue;

        candidates.push({
            start: leftStart,
            end: rightEnd,
            original,
            actual: resolution.path,
        });
    }

    if (!candidates.length) return { text, repairs };

    // Apply replacements right-to-left so earlier offsets stay valid.
    candidates.sort((a, b) => b.start - a.start);
    let out = text;
    let lastStart = Number.MAX_SAFE_INTEGER;
    for (const candidate of candidates) {
        if (candidate.end > lastStart) continue;
        out = out.slice(0, candidate.start) + candidate.actual + out.slice(candidate.end);
        repairs.push({ original: candidate.original, actual: candidate.actual });
        lastStart = candidate.start;
    }

    return { text: out, repairs };
}

// ------------------------------------------------------------------ shell commands

/**
 * Mirror the exact shell-command canonicalization pipeline Path Guard applies during
 * tool execution, so model-context repair matches what actually ran on disk.
 */
function canonicalizeShellCommand(command: string, cwd: string, name: string): string {
    if (name === "bash") {
        const quoted = canonicalizeQuotedShellPaths(command, cwd);
        return canonicalizeNestedPowerShellCommand(quoted.command, cwd).command;
    }
    // powershell
    const quoted = canonicalizeQuotedShellPaths(command, cwd);
    const unquoted = canonicalizeUnquotedShellPaths(quoted.command, cwd);
    return canonicalizeSetContentWriteTarget(unquoted.command, cwd).command;
}

// ------------------------------------------------------------------ tool calls

function isJsonObject(value: unknown): value is JsonObject {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

function repairToolCall(call: ToolCall, cwd: string): { call: ToolCall; repaired: boolean; repairs: Repair[] } {
    const name = call.name.toLowerCase();

    // Shell tools: the path lives inside `command`.
    if (name === "bash" || name === "powershell") {
        if (typeof call.arguments.command !== "string") return { call, repaired: false, repairs: [] };
        const canonical = canonicalizeShellCommand(call.arguments.command, cwd, name);
        if (canonical === call.arguments.command) return { call, repaired: false, repairs: [] };
        const next = { ...call.arguments, command: canonical } as JsonObject;
        return {
            call: { ...call, arguments: next },
            repaired: true,
            repairs: [{ original: call.arguments.command, actual: canonical }],
        };
    }

    // Structured tools with a `path` argument.
    if (isJsonObject(call.arguments) && typeof call.arguments.path === "string") {
        const resolution =
            name === "write" || name === "edit"
                ? resolveWritePath(call.arguments.path, cwd)
                : resolveExistingPath(call.arguments.path, cwd);
        if (resolution.kind !== "corrected") return { call, repaired: false, repairs: [] };
        const next = { ...call.arguments, path: resolution.path } as JsonObject;
        return {
            call: { ...call, arguments: next },
            repaired: true,
            repairs: [{ original: call.arguments.path, actual: resolution.path }],
        };
    }

    return { call, repaired: false, repairs: [] };
}

// ------------------------------------------------------------------ top level

function isTextContent(item: unknown): item is TextContent {
    return (item as { type?: string })?.type === "text";
}

function isThinkingContent(item: unknown): item is ThinkingContent {
    return (item as { type?: string })?.type === "thinking";
}

function isToolCall(item: unknown): item is ToolCall {
    return (item as { type?: string })?.type === "toolCall";
}

/**
 * Repair every assistant content item against the filesystem. Pure: the input array
 * and its items are never mutated. `changed` is true only if at least one repair was
 * applied, in which case a fresh array is returned.
 */
export function repairAssistantContent(
    content: AssistantContent,
    cwd: string
): AssistantContentRepair {
    const repairs: Repair[] = [];
    const next: AssistantContent = [];
    let changed = false;

    for (const item of content) {
        if (isTextContent(item)) {
            const { text: repairedText, repairs: itemRepairs } = repairPathSpansInText(
                item.text,
                cwd
            );
            if (itemRepairs.length) {
                changed = true;
                next.push({ ...item, text: repairedText });
                repairs.push(...itemRepairs);
            } else {
                next.push(item);
            }
            continue;
        }

        if (isThinkingContent(item)) {
            const { text: repairedThinking, repairs: itemRepairs } = repairPathSpansInText(
                item.thinking,
                cwd
            );
            if (itemRepairs.length) {
                changed = true;
                next.push({ ...item, thinking: repairedThinking });
                repairs.push(...itemRepairs);
            } else {
                next.push(item);
            }
            continue;
        }

        if (isToolCall(item)) {
            const { call: repairedCall, repaired, repairs: itemRepairs } = repairToolCall(item, cwd);
            if (repaired) {
                changed = true;
                next.push(repairedCall);
                repairs.push(...itemRepairs);
            } else {
                next.push(item);
            }
            continue;
        }

        next.push(item);
    }

    return { content: changed ? next : content, changed, repairs };
}

// ------------------------------------------------------------------ boundary draft

/**
 * Build the `context_edit` boundary draft for a repaired assistant message. This draft
 * is applied by Pi only to the model-facing *projection* (via `buildSessionProjection`);
 * the raw session history is never modified, so the original assistant message remains
 * intact for audit and compaction.
 */
export function buildContextEditDraft(
    targetId: string,
    content: AssistantContent | ContextEditableContent
): ContextEditEntryDraft {
    return {
        type: "context_edit",
        targetId,
        replacement: { content },
    };
}

// ------------------------------------------ correction notification / telemetry

/**
 * Build a *successful-correction* notification.
 *
 * Canonical-only contract: this MUST expose ONLY the authoritative corrected
 * path (e.g. `corrected → src/Kryxn.Core/Tasks/Foo.cs`). It MUST never contain
 * the malformed/original spelling that was corrected. Callers pass the list of
 * canonical paths (the `actual`/`path` destination), so the original is never
 * reachable here.
 */
export function buildCorrectionNotification(
    label: string,
    canonicalPaths: string[]
): string {
    return [
        label,
        ...canonicalPaths.map((path) => `corrected → ${path}`),
    ].join("\n");
}

/**
 * Bounded, canonical-only session telemetry for successful corrections.
 *
 * Retains the exact total correction count plus an aggregated per-destination
 * counter keyed by the AUTHORITATIVE canonical path. Malformed/original
 * spellings are NEVER stored. Distinct destinations are capped at
 * `maxDestinations` (FIFO eviction) so telemetry storage cannot grow without
 * bound.
 */
export class CorrectionTelemetry {
    readonly counts = new Map<string, number>();

    constructor(private readonly maxDestinations = 500) {
        if (!Number.isFinite(maxDestinations) || maxDestinations <= 0) {
            throw new Error("CorrectionTelemetry: maxDestinations must be a positive number");
        }
    }

    /** Exact total number of recorded successful corrections. */
    get total(): number {
        return [...this.counts.values()].reduce((sum, n) => sum + n, 0);
    }

    /** Record one successful correction against its canonical destination. */
    record(canonical: string): void {
        const existing = this.counts.get(canonical) ?? 0;
        this.counts.set(canonical, existing + 1);
        // Bound distinct-destination growth: drop the oldest when a brand-new
        // destination would exceed the cap. The total count stays exact.
        if (existing === 0 && this.counts.size > this.maxDestinations) {
            const oldest = this.counts.keys().next().value;
            if (oldest !== undefined) this.counts.delete(oldest);
        }
    }

    /** Canonical-only, count-descending snapshot for reporting. */
    report(): { path: string; count: number }[] {
        return [...this.counts.entries()]
            .map(([path, count]) => ({ path, count }))
            .sort((a, b) => b.count - a.count);
    }
}

/**
 * Build the `/path-guard` status report. Enabled status, authorized root and
 * the exact correction total are always present. Canonical destinations (if any
 * were corrected this session) are listed canonical-only; the malformed /
 * original spelling is never represented anywhere in the output.
 */
export function buildPathGuardStatus(
    repositoryRoot: string | undefined,
    telemetry: CorrectionTelemetry
): string {
    const rootLabel =
        repositoryRoot === undefined
            ? "none (no git repository root established)"
            : repositoryRoot;

    const lines = [
        "Pi Path Guard: ON",
        `Root: ${rootLabel}`,
        `Corrections this session: ${telemetry.total}`,
    ];

    const destinations = telemetry.report();
    if (destinations.length > 0) {
        lines.push("Canonical destinations corrected this session:");
        for (const { path, count } of destinations) {
            lines.push(
                `${path} — ${count} correction${count === 1 ? "" : "s"}`
            );
        }
    }

    lines.push("");
    lines.push("Existing paths: whitespace canonicalization");
    lines.push("New writes: existing parent canonicalization");
    lines.push(
        "Shell commands: quoted + native/nested PowerShell canonicalization enabled"
    );

    return lines.join("\n");
}
